const D = { scale:1, energy:.55, hue:48, speed:1, density:.5, x:.5, y:.42, pose:'serene', style:'gouache', act:'nightfall', chub:.5, glow:.6, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const u=Math.min(width,height);
const chub=.85+P.chub*.35;
const R=u*0.225*P.scale*(0.9+chub*0.12);
const bt=K.beat*P.speed;
const en=P.energy*(.55+.45*K.intensity);
const H=md(P.hue,360);
const style=P.style;
const gou=style==='gouache', eng=style==='engraving', chi=style==='chiaroscuro', riso=style==='riso', lan=style==='lantern';

// t0 reset guard
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

// section-change wink
if(S.sec==null)S.sec=K.section;
if(K.section!==S.sec){S.winkT=K.t;S.sec=K.section;}
let winking=(S.winkT!=null&&K.t-S.winkT<0.55)||(P.pose==='wink'&&frc(bt*0.5)<0.22);

// ---- seed caches ----
if(S.seedUsed!==P.seed){
  S.seedUsed=P.seed;
  S.crater=[];
  for(let i=0;i<13;i++){const a=fr(i*3+1)*6.2832,rr=Math.sqrt(fr(i*3+2))*0.78;S.crater.push({x:Math.cos(a)*rr,y:Math.sin(a)*rr,r:0.05+fr(i*5+3)*0.12});}
  S.star=[];
  for(let i=0;i<64;i++)S.star.push({x:fr(i*7+10),y:fr(i*7+11)*0.92,s:0.3+fr(i*7+12)*0.9,ph:fr(i*7+13)*6.2832,tw:0.5+fr(i*7+14)});
  S.dab=[];
  for(let i=0;i<110;i++){const a=fr(i*9+20)*6.2832,rr=Math.sqrt(fr(i*9+21))*0.99;S.dab.push({x:Math.cos(a)*rr,y:Math.sin(a)*rr,r:0.03+fr(i*9+22)*0.06,t:fr(i*9+23)});}
  S.haloKey=null;
}

// halo sprite
const HK=Math.round(R);
if(!S.halo||S.haloKey!==HK){
  S.haloKey=HK;
  const sz=Math.max(24,Math.round(R*3));
  S.halo=createGraphics(sz,sz);
  S.halo.noStroke();
  const c=sz/2;
  for(let r=sz/2;r>0;r--){S.halo.fill(0,0,100,2.4*(1-r/(sz/2)));S.halo.ellipse(c,c,r*2,r*2);}
}

// ---- moon motion ----
const driftX=Math.sin(K.t*0.11)*R*0.13+Math.sin(K.t*0.047)*R*0.06;
const driftY=Math.cos(K.t*0.09)*R*0.11-K.pulse*R*0.07*en+Math.sin(K.t*0.19)*R*0.05;
const tilt=Math.sin(K.t*0.13)*0.05*en+Math.sin(K.t*0.037)*0.03;
const breathe=1+0.02*K.swell*en;

// mood 0..1 (tracks intensity + pose)
let mood=clp(K.intensity*0.65+0.28+(P.pose==='full_beam'?0.35:0)-(P.pose==='sleepy'?0.55:0),0,1);

// light / phase
let lightA=-0.9; // direction of light (upper-right-ish)
let phaseOff=0.34; // shadow crescent offset fraction
if(P.act==='phases'){phaseOff=0.15+ (Math.sin(K.t*0.05)*0.5+0.5)*0.85; lightA=-0.9+Math.sin(K.t*0.05)*0.6;}
const gibbous=P.pose==='gibbous';

// ---------- STARS (screen space) ----------
push();
blendMode(ADD); noStroke();
const nst=Math.floor(P.density*56);
for(let i=0;i<nst;i++){
  const st=S.star[i];
  const sx=st.x*width;
  const sy=st.y*height;
  const tw=Math.sin(K.t*(0.6+st.tw)+st.ph)*0.5+0.5;
  const al=(7+tw*20)*(0.6+A.treble*1.3);
  if(riso)fill((i%2)?205:335,60,100,clp(al,0,38));
  else if(eng)fill(0,0,88,clp(al*0.7,0,26));
  else fill(md(H+45,360),18,100,clp(al,0,38));
  const ss=st.s*u*0.0045*(1+tw*0.5);
  ellipse(sx,sy,ss,ss);
}
blendMode(BLEND);
pop();

// ---------- MOON ----------
push();
translate(width*P.x+driftX, height*P.y+driftY);
rotate(tilt);
scale(breathe);

// halo
const halPulse=1+0.11*K.swell*en+0.06*Math.sin(K.t*0.5)+A.bass*0.15+K.pulse*0.05*en;
const halSz=R*3*halPulse*(0.85+P.glow*0.65);
push();
blendMode(ADD);
const hcol=lan?H:(chi?md(H-10,360):md(H+8,360));
tint(hcol,chi?28:36,100,clp(9+K.intensity*15+A.bass*13+P.glow*13,0,52));
imageMode(CENTER);
image(S.halo,0,0,halSz,halSz);
imageMode(CORNER);
noTint();
blendMode(BLEND);
pop();

// ---- disc paint (clipped to circle) ----
push();
drawingContext.save();
drawingContext.beginPath();
drawingContext.arc(0,0,R,0,Math.PI*2);
drawingContext.clip();

if(chi){
  // form-from-light: dark base, luminous crescent, no outline
  noStroke(); fill(md(H+8,360),34,16); rect(-R,-R,2*R,2*R);
  blendMode(ADD);
  const lx=Math.cos(lightA)*R*0.5, ly=Math.sin(lightA)*R*0.5;
  for(let r=1.15;r>0;r-=0.045){ fill(md(H+6,360),22,100,4.2); ellipse(lx,ly,R*2*r,R*2*r); }
  // subtle crater shadows only where lit
  blendMode(MULTIPLY);
  for(const cr of S.crater){ fill(0,0,0,26); ellipse(cr.x*R,cr.y*R,cr.r*R*1.6,cr.r*R*1.4); }
  blendMode(BLEND);
}else if(riso){
  // 2-ink misregistration + halftone
  const o=R*0.022;
  noStroke();
  fill(205,58,92,66); ellipse(-o,-o*0.7,R*2,R*2);      // cyan plate
  fill(338,66,96,60); ellipse(o,o*0.7,R*2,R*2);         // magenta plate
  // halftone dots in shadow crescent (magenta)
  const sc0=phaseOff*R;
  for(const d of S.dab){ const dx=d.x*R,dy=d.y*R; const inShadow=(dx+R*0.5)< -sc0+R*0.5+ (gibbous?R*0.2:0); if(dx< -sc0*0.2){ fill(338,70,90,70); ellipse(dx+o,dy+o*0.7,d.r*R*1.3,d.r*R*1.3);} }
}else if(eng){
  // parchment + cross-hatch shadow + stipple
  noStroke(); fill(42,10,95); rect(-R,-R,2*R,2*R);
  stroke(30,25,26); strokeWeight(Math.max(0.6,R*0.006));
  for(let k=-14;k<=14;k++){ const yy=k/14*R; const shade=(yy>R*(0.05))||true; // hatch density grows lower-left
    const xoff=-R*phaseOff;
    // primary hatch across shadow band
    const x0=xoff-R, x1=xoff+R*0.15;
    if(k%1===0){ line(clp(x0,-R,R),yy,clp(x1,-R,R),yy+R*0.05); }
  }
  // diagonal cross-hatch in lower-left shadow
  for(let k=-16;k<=8;k++){ const off=k*R*0.09; line(-R,off-R*0.4-R*phaseOff+R*0.3, off-R*phaseOff-R*0.1, -R); }
  // stipple grain
  noStroke();
  for(const d of S.dab){ fill(30,22,22,55*(0.4+d.t)); ellipse(d.x*R,d.y*R,d.r*R*0.7,d.r*R*0.7); }
}else if(lan){
  // luminous translucent lantern
  noStroke();
  for(let r=1.0;r>0;r-=0.12){ fill(md(H+ (1-r)*30,360),clp(70-r*30,10,80),100,26); ellipse(0,0,R*2*r,R*2*r); }
  blendMode(ADD);
  for(const cr of S.crater){ fill(md(H+20,360),40,100,20); ellipse(cr.x*R,cr.y*R,cr.r*R*1.4,cr.r*R*1.4); }
  blendMode(BLEND);
}else{
  // gouache: matte cream, terminator shading, brush dabs, craters
  noStroke(); fill(md(H,360),16,96); rect(-R,-R,2*R,2*R);
  // painterly tonal dabs (light modeling from upper-right)
  for(const d of S.dab){ const dx=d.x*R,dy=d.y*R; const litv=(-dx-dy)/(R*1.4); // upper-right lighter
    const b=clp(90+litv*10,72,100), s=clp(18-litv*8,6,26);
    fill(md(H+litv*6,360),s,b,42*(0.5+d.t)); ellipse(dx,dy,d.r*R*2.4,d.r*R*2.2); }
  // shadow crescent (lower-left) — soft
  blendMode(MULTIPLY);
  const sox=-R*phaseOff*1.4, soy=R*phaseOff*0.7;
  for(let r=1.25;r>0;r-=0.06){ fill(md(H-14,360),40,72,5); ellipse(sox+R*0.1,soy+R*0.1,R*2*r,R*2*r); }
  blendMode(BLEND);
  // craters
  for(const cr of S.crater){ const cx=cr.x*R,cy=cr.y*R,crr=cr.r*R;
    fill(md(H-6,360),22,80,55); ellipse(cx,cy,crr*2,crr*1.85);
    fill(md(H+6,360),12,99,50); ellipse(cx-crr*0.35,cy-crr*0.35,crr*1.1,crr*1.0);
    fill(md(H-10,360),30,66,40); ellipse(cx+crr*0.3,cy+crr*0.32,crr*0.9,crr*0.85);
  }
}
drawingContext.restore();
pop();

// disc rim / outline per style
noFill();
if(gou){ stroke(md(H-8,360),28,74,50); strokeWeight(R*0.02); circle(0,0,R*2); }
else if(eng){ stroke(30,25,20,90); strokeWeight(Math.max(1,R*0.014)); circle(0,0,R*2); }
else if(lan){ stroke(md(H+30,360),55,100,60); strokeWeight(R*0.02); circle(0,0,R*2*1.005); }
else if(riso){ /* no crisp rim */ }
else if(chi){ /* form from light only */ }

// beat rim-light kick
if(!chi){ push(); blendMode(ADD); noFill(); stroke(md(H+10,360),clp(20+A.bass*40,10,70),100,clp((K.pulse*30+A.bass*36)*en,0,60)); strokeWeight(R*0.03); arc(0,0,R*2,R*2,-1.9,0.4); blendMode(BLEND); pop(); }

// ---------- FACE ----------
const gsh=gibbous?R*0.16:0; // gibbous shifts features toward lit side
const eyeY=-R*0.16, eyeDX=R*0.30, eyeR=R*0.105;
const inkC=eng?[28,30,18]:riso?[300,50,30]:chi?[H,20,86]:lan?[md(H+180,360),40,55]:[md(H-6,360),30,40];
function feat(h,s,b,a){ if(eng){stroke(inkC[0],inkC[1],inkC[2],a==null?100:a);} else if(chi){stroke(inkC[0],inkC[1],inkC[2],(a==null?100:a)*0.6);} else {stroke(h,s,b,a==null?100:a);} }
function featF(h,s,b,a){ if(eng){noStroke();fill(inkC[0],inkC[1],inkC[2],a==null?100:a);} else if(chi){noStroke();fill(inkC[0],inkC[1],inkC[2],(a==null?100:a)*0.5);} else {noStroke();fill(h,s,b,a==null?100:a);} }

push();
translate(gsh,0);
// eyebrows (mood: raised=bright, low=sleepy)
const brow=(mood-0.5)*R*0.06;
feat(inkC[0],inkC[1],inkC[2]); strokeWeight(R*0.02); noFill();
const browY=eyeY-R*0.16-brow*0.4;
arc(-eyeDX,browY,eyeR*1.9,eyeR*1.4,Math.PI+0.2-mood*0.3,6.2832-0.2);
if(!winking)arc(eyeDX,browY,eyeR*1.9,eyeR*1.4,Math.PI+0.2,6.2832-0.2+mood*0.3);

// eyes
const lidBlink=frc(K.t*0.13+fr(3)*4)<0.05;
const lid=P.pose==='sleepy'?0.62:0.0;
function eye(ex,closed){
  push(); translate(ex,eyeY);
  if(closed){ feat(inkC[0],inkC[1],inkC[2]); strokeWeight(R*0.024); noFill(); arc(0,0,eyeR*2,eyeR*1.5,0.25,Math.PI-0.25); pop(); return; }
  // white
  if(!chi&&!eng){ noStroke(); fill(0,0,98,92); ellipse(0,0,eyeR*2,eyeR*2*(1-lid*0.6)); }
  else { feat(inkC[0],inkC[1],inkC[2]); strokeWeight(R*0.018); noFill(); ellipse(0,0,eyeR*2,eyeR*2*(1-lid*0.6)); }
  // iris follows slow drift
  const gx=Math.sin(K.t*0.3)*eyeR*0.28, gy=Math.cos(K.t*0.23)*eyeR*0.18;
  featF(md(H+150,360),50,45,100); ellipse(gx,gy,eyeR*1.05,eyeR*1.05*(1-lid*0.5));
  featF(0,0,12,100); ellipse(gx,gy,eyeR*0.5,eyeR*0.5);
  if(!chi){ noStroke(); fill(0,0,100,80); ellipse(gx-eyeR*0.2,gy-eyeR*0.2,eyeR*0.28,eyeR*0.28); }
  pop();
}
eye(-eyeDX, lidBlink);
eye(eyeDX, winking||lidBlink);

// nose (tiny crescent)
if(!eng||true){ feat(inkC[0],inkC[1],inkC[2],70); strokeWeight(R*0.016); noFill(); arc(0,R*0.02,R*0.09,R*0.11,0.5,Math.PI-0.5); }

// mouth (mood-driven smile, breathes open a touch)
const open=R*0.02*(K.swell*0.6+0.4)*en+ (P.pose==='full_beam'?R*0.05:0);
const smile=R*(0.10+mood*0.16);
const my=R*0.30;
feat(inkC[0],inkC[1],inkC[2]); strokeWeight(R*0.028); noFill();
beginShape();
vertex(-R*0.19,my- (mood-0.5)*R*0.05);
bezierVertex(-R*0.06,my+smile, R*0.06,my+smile, R*0.19,my-(mood-0.5)*R*0.05);
endShape();
if(open>R*0.03&&!chi){ featF(340,55,45,85); ellipse(0,my+smile*0.55,R*0.16,open*2.2); }

// cheeks (gouache warmth)
if(gou||lan){ push(); blendMode(ADD); noStroke(); fill(md(H-20,360),clp(40+mood*20,20,70),100,18+mood*14); ellipse(-R*0.5,R*0.18,R*0.4,R*0.28); ellipse(R*0.5,R*0.18,R*0.4,R*0.28); blendMode(BLEND); pop(); }
pop(); // face group
pop(); // moon group
